# Enthält den Abschnitt zu Flugverspätung und Gepäck (in AT ein eigener Ratgeber). Versicherungsangaben stammen aus den
# erfassten Bedingungen der DE-Karten (insText in de-recherche); Jahresgebühren und Kartennamen live aus den Kartendaten.
# Aufruf aus ratgeber.build('de'): register(art,P,best,K,nprv,eur,KM)
import html
E=lambda s: html.escape(str(s)) if s is not None else ''

def _tbl(head,rows):
    h=''.join(f'<th>{c}</th>' for c in head)
    b=''.join('<tr>'+''.join(f'<td>{c}</td>' for c in r)+'</tr>' for r in rows)
    return f'<div class="tbl wide"><table><thead><tr>{h}</tr></thead><tbody>{b}</tbody></table></div>'

