def register(art,P,best,K,nprv,eur,KM):
    T={c['slug']:c for c in K}
    for s,*_ in ROWS:
        if s not in T: raise SystemExit(f'ratgeber_reise_de: unbekannte Karte {s}')
    priv=[c for c in K if c['art']=='Privat']
    def L(slug,label=None): return f'<a class="lnk" href="{P}de/kreditkarten/{slug}/">{E(label or T[slug]["titel"])}</a>'
    def fee(c):
        f=c.get('fee'); t='kostenlos' if f==0 else (f'{eur(f)} €' if f is not None else KA)
        return t+(' <small>(nur für bestimmte Gruppen)</small>' if c.get('nurfuer') else '')
    n_storno=len([c for c in priv if (c.get('tier') or 0)>=2]); n_basis=len([c for c in priv if c.get('tier')==1]); n_none=len([c for c in priv if c.get('tier')==0])
    rows=sorted(ROWS,key=lambda r:(T[r[0]].get('fee') if T[r[0]].get('fee') is not None else 1e9,T[r[0]]['titel']))
    tbl=_tbl(['Karte','Jahresgebühr','Reiserücktritt bis','Selbstbehalt','Auslandskranken','Gepäck','Verspätung','Mietwagen','Was du tun musst'],
             [(L(s),fee(T[s]),E(a),E(b),E(c),E(d),E(e),E(f),E(g)) for s,a,b,c,d,e,f,g in rows])
    eu=_tbl(['Flugdistanz','Betreuung (Verpflegung, Hotel) ab','Ausgleichszahlung ab 3 Stunden Verspätung am Ziel'],[
        ('bis 1.500 km','2 Stunden','250 € pro Person'),('über 1.500 km innerhalb der EU sowie 1.500 bis 3.500 km','3 Stunden','400 € pro Person'),('über 3.500 km','4 Stunden','600 € pro Person')])
    duel=_tbl(['',L('tf-bank-mastercard-gold'),L('advanzia-bank-gebuehrenfrei-mastercard-gold'),L('bank-norwegian-visa-kreditkarte')],[
        ('<b>Reiserücktritt</b>','3.000 €','3.000 €','2.000 € pro Person, 4.000 € pro Reise (laut Portal)'),
        ('<b>Selbstbehalt</b>','100 € pro Person, fix','20 %, mindestens 100 €','20 %, mindestens 185 €'),
        ('<b>Bedingung</b>','50 % der Transportkosten (bei Pkw: Unterkunft) mit der Karte','50 % der Transport- oder Pauschalreisekosten; nur Reisen außerhalb Deutschlands','50 % der Transportkosten'),
        ('<b>Altersgrenze</b>','Rücktritt und Krankheit bis 75','ab 70 nur 21 Tage pro Reise, Schutz endet mit 75','bis einschließlich 65'),
        ('<b>Auslandskranken</b>','1.000.000 €','1.000.000 € (100 € Selbstbehalt)',KA),
        ('<b>Gepäck und Verspätung</b>','2.500 €; Transport ab 6 Stunden 85 €, Gepäck 150 €','2.500 €; je 250 €',KA),
        ('<b>Mitversichert</b>','bis 4 Mitreisende','Partner und Kinder',KA)])
    ext=lambda u,t: f'<a class="lnk" href="{u}" target="_blank" rel="noopener">{t}</a>'
    Q_EU=ext('https://www.verbraucherzentrale.de/wissen/reise-mobilitaet/unterwegs-sein/fluggastrechte-auf-einen-blick-wann-habe-ich-welchen-anspruch-10366','Verbraucherzentrale')
    Q_MC=ext('https://www.test.de/Verlorenes-Gepaeck-Aerger-am-Gepaeckband-1767091-1768178/','Stiftung Warentest')
    Q_ADR=ext('https://www.evz.de/services/adr/schlichtungsstellen-deutschland/fernreisen-nahverkehr/','Europäisches Verbraucherzentrum')
    reisen=f'{best}reisen/'
    art('de','reiseversicherung',
      h1='Reiseversicherung über die Kreditkarte: Welche Karte dich in Deutschland wirklich absichert',
      mt='Kreditkarte mit Reiseversicherung: Vergleich für Deutschland 2026 | Finvallo',
      desc='Kreditkarten mit Reiseversicherung in Deutschland: Stornosummen, Selbstbehalt, Auslandskranken, Gepäck und Flugverspätung aller Karten im Vergleich.',
      lede=f'{n_storno} von {nprv} Privatkarten haben einen Reiserücktritt dabei. Ob er zahlt, hängt davon ab, womit du gebucht hast, wie lange du reist und wie alt du bist.',
      kurz=(f'Von den {nprv} Privatkarten in unserem Deutschland-Vergleich enthalten {n_storno} eine Reiseversicherung mit Reiserücktritt, {n_basis} nur einzelne Bausteine und {n_none} gar keine; beim Rest fehlen auswertbare Bedingungen. '
            f'Ohne Jahresgebühr und mit Storno bis 3.000 €: {L("tf-bank-mastercard-gold")} und {L("advanzia-bank-gebuehrenfrei-mastercard-gold")} (baugleich: {L("web-cent-mastercard-gold-gmx-web-de")}); die {L("bank-norwegian-visa-kreditkarte")} ist ebenfalls gratis, ihre Summen kennen wir aber nur aus zweiter Hand. '
            f'Die höchsten Stornosummen haben {L("n26-go")}, {L("consorsbank-visa-card-gold")}, {L("openbank-bestcard-premium")} und die ADAC-Pakete mit 10.000 €. Eine Mietwagen-Vollkasko gibt es bei {L("american-express-platinum-card")}, den Miles &amp; More Karten, {L("eurowings-kreditkarte-premium")}, {L("targobank-premium-karte")}, {L("easybank-kreditkarte-platinum")} und {L("openbank-bestcard-premium")}. '
            f'Typisch für deutsche Gold-Karten: Die Auslandskrankenversicherung gilt oft ohne Karteneinsatz (Sparkasse, Postbank, Commerzbank, HypoVereinsbank, Miles &amp; More), der Reiserücktritt nur, wenn du die Reise mit der Karte bezahlt hast.'),
      secs=[
       ('Was „Reiseversicherung inklusive“ in Deutschland wirklich heißt',f'''<div class="prose"><p>Hinter dem Wort stecken bis zu fünf getrennte Bausteine, und kaum eine Karte hat alle: Reiserücktritt und Reiseabbruch (Storno), Auslandsreise-Krankenversicherung mit Rücktransport, Gepäck- und Verspätungsschutz, Mietwagen-Kasko und Unfall- oder Haftpflichtversicherung auf Reisen. Die {L("deutsche-bank-mastercard-gold")} enthält zum Beispiel nur die Krankenversicherung, die {L("american-express-card")} nur Verspätung und Verkehrsmittel-Unfall, die {L("eurowings-kreditkarte-classic")} nur den Storno. Alle drei werben mit Reiseschutz.</p>
<p>Zwei Muster unterscheiden Deutschland von Österreich. Erstens: Bei vielen Gold-Karten der Filialbanken gilt die Auslandskrankenversicherung auch ohne Karteneinsatz und für die Familie; {L("sparkasse-kreditkarte-gold")}, {L("postbank-mastercard-gold")}, {L("commerzbank-goldkreditkarte")}, {L("hypovereinsbank-mastercard-gold")} und die Miles &amp; More Karten versichern Arztkosten, sobald du die Karte besitzt. Der Reiserücktritt verlangt dagegen fast überall, dass die Reise mindestens zur Hälfte oder ganz mit der Karte bezahlt wurde. Zweitens: Eine Mietwagen-Vollkasko ist in Deutschland häufiger, sie steckt in zehn Karten unseres Vergleichs, dazu Selbstbehalt-Versicherungen bei Consorsbank, bunq und ADAC.</p>
<p>Was eine Karte wirklich enthält, steht nur in den Versicherungsbedingungen. Die Summen in diesem Artikel sind Höchstgrenzen aus diesen Dokumenten, keine fixen Auszahlungen. Wo uns nur die Werbung oder ein Vergleichsportal vorlag, steht das in der Tabelle so.</p></div>'''),
       ('Die drei Bedingungen, an denen es im Schadenfall scheitert',f'''<div class="prose"><p><b>1. Die Reise muss mit der Karte bezahlt sein.</b> Die Schwelle setzt jede Bank anders. TF Bank verlangt 50 % der Transportkosten, bei Anreise mit dem Auto 50 % der Unterkunft. Advanzia und die baugleichen Karten (GMX/WEB.DE, Turkish Airlines, Hilton Honors) 50 % der Transport- oder Pauschalreisekosten. Deutschland-Kreditkarte Gold, Hanseatic GoldCard, Sparkasse Gold und Tomorrow Plus verlangen 50 % der Reise. Die Miles &amp; More Karten, 1822direkt, easybank, Postbank und die ADAC-Pakete wollen die Reise vollständig mit der Karte bezahlt sehen. easybank Platinum staffelt: 20 % für den Rücktritt, 50 % für den Abbruch. Ohne Zahlungsbedingung kommen beim Storno nur HypoVereinsbank Gold, Commerzbank Gold und Premium sowie N26 aus.</p>
<p><b>2. Die Reise darf nicht zu lang sein.</b> Die Krankenversicherung gilt pro Reise meist 60 bis 90 Tage: ADAC 45 Tage, HypoVereinsbank 45, Sparkasse 56, Openbank 60, Postbank, Commerzbank, Tomorrow und American Express Gold 62, easybank Gold und Eurowings 42, Advanzia, Deutsche Bank und Miles &amp; More 90, American Express Platinum und BMW 120. Revolut Premium und Metal versichern nur 30 Tage. Für ein Auslandssemester reicht keine davon ohne Zusatzpolice.</p>
<p><b>3. Altersgrenzen.</b> Bank Norwegian versichert bis einschließlich 65, TF Bank und Advanzia bis 75, Sparkasse Gold bei der Krankenversicherung bis 75; Advanzia kürzt ab 70 die versicherte Reisedauer auf 21 Tage. Die anderen Anbieter nennen in den ausgewerteten Bedingungen keine Grenze, was nicht heißt, dass es keine gibt.</p></div>'''),
       ('Alle Karten mit Reiseversicherung im Vergleich','<p class="note">Sortiert nach Jahresgebühr. Alle Beträge sind Höchstsummen aus den Versicherungsbedingungen. „nein“ heißt, der Baustein ist laut Bedingungen nicht enthalten; „keine Angabe“ heißt, dass wir keinen Wert gefunden haben. Karten, die es nur für bestimmte Gruppen gibt (Lufthansa-Statuskunden), sind gekennzeichnet.</p>'+tbl+
        f'''<div class="prose"><p>Nicht in der Tabelle, weil nur einzelne Bausteine enthalten sind: {L("deutsche-bank-mastercard-gold")} (Auslandskranken für 90 Tage, ohne Karteneinsatz), {L("american-express-card")} (Verspätung und Verkehrsmittel-Unfall), {L("american-express-blue-card")} (nur Verkehrsmittel-Unfall), {L("adac-kreditkarte-mit-paket-schutz")} (Mietwagen-Selbstbehalt bis 3.000 €), {L("tomorrow-change")} (Auslandskranken 62 Tage), {L("revolut-premium")} und {L("revolut-metal")} (Auslandskranken, 30 Tage, Reise mit Revolut bezahlt), {L("klarna-premium")} (Kranken, Gepäck, Mietwagen, kein Storno). Gar keine Reiseversicherung haben die übrigen Karten, darunter alle Debitkarten in der Gratis-Stufe (DKB, ING, N26 Standard, C24, Trade Republic) und die meisten Classic-Karten der Filialbanken.</p>
<p class="note"><a class="lnk" href="{reisen}">Bestenliste für Reisen →</a></p></div>'''),
       ('Kostenlos und trotzdem versichert: TF Bank, Advanzia, Bank Norwegian','<div class="prose"><p>Drei Karten ohne Jahresgebühr enthalten in Deutschland einen Reiserücktritt. TF Bank und Advanzia versichern beide 3.000 € Storno, 1.000.000 € Arztkosten und 2.500 € Gepäck; der Unterschied liegt im Selbstbehalt, im Alter und bei Advanzia in einer Regel, die viele übersehen: Die Versicherung gilt nur für Reisen außerhalb Deutschlands. Ein storniertes Hotel an der Ostsee ist dort nur versichert, wenn die Übernachtung vorab mit der Karte bezahlt wurde.</p></div>'+duel+
        f'''<div class="prose"><p>Bei einer stornierten Pauschalreise für 2.000 € zahlt TF Bank 1.900 €, Advanzia 1.600 € (20 % sind 400 €), Bank Norwegian 1.600 € (20 %, mindestens 185 €). Bei 600 € Schaden zahlen TF Bank 500 €, Advanzia 480 € (20 % sind 120 €) und Bank Norwegian 415 €. Je teurer die Reise, desto deutlicher liegt TF Bank vorn. Die Angaben zu Bank Norwegian stammen von einem Vergleichsportal; die Bank selbst nennt auf ihrer Seite nur „Reise- und Reiserücktrittsversicherung inklusive“. Vor einer Buchung, die auf diesen Schutz baut, die Bedingungen anfordern. Alle drei Karten verzinsen Bargeld ab dem Buchungstag; was das kostet, steht im Ratgeber <a href="../bargeld-abheben/">Geld abheben</a>.</p></div>'''),
       ('Flugverspätung, Koffer verspätet oder verloren: was Airline und Karte zahlen',f'''<div class="prose"><p>Bei Verspätungen und Gepäck ist die Karte der zweite Topf. Zuerst haftet die Airline: Nach der EU-Fluggastrechteverordnung bekommst du bei mindestens drei Stunden Verspätung am Ziel eine Ausgleichszahlung, gestaffelt nach Flugdistanz, außer die Airline weist außergewöhnliche Umstände nach. Schon vorher muss sie Verpflegung stellen, bei einer Übernachtung das Hotel. Für Gepäck haftet sie nach dem Montrealer Übereinkommen bis 1.519 Sonderziehungsrechte pro Passagier, rund 1.900 €; Beschädigungen musst du binnen sieben Tagen, verspätetes Gepäck binnen 21 Tagen schriftlich reklamieren, nach 21 Tagen gilt der Koffer als verloren.</p></div>'''+eu+
        f'''<div class="prose"><p class="note">Beträge pro Person. Eine 2026 ausgehandelte Reform der Verordnung lässt Schwelle und Beträge unverändert.</p>
<p>Die Kartenversicherung ersetzt obendrauf belegte Ausgaben, nie Pauschalen: Ersatzkäufe, wenn der Koffer nachkommt, Verpflegung und Hotel unterhalb der EU-Schwelle, und den Teil eines Kofferinhalts über der gesetzlichen Grenze. Am großzügigsten sind {L("american-express-gold-card")} (Flug ab vier Stunden 175 €, Gepäck 325 € und nach 48 Stunden weitere 475 €), {L("american-express-platinum-card")} (200 bis 800 €), {L("n26-go")} und {L("n26-metal")} (Reise- oder Gepäckverspätung bis 500 €), {L("deutschland-kreditkarte-gold")} und {L("tomorrow-plus")} (bis 500 €), {L("deutsche-bank-mastercard-travel")} (Gepäckverspätung 500 €). Advanzia und die baugleichen Karten zahlen je 250 €, TF Bank 85 € Verpflegung ab sechs Stunden und 150 € fürs Gepäck, {L("bunq-elite")} 250 € ab vier Stunden und 340 € fürs Gepäck, {L("klarna-max")} 250 € erst ab acht Stunden.</p>
<p>Beim verlorenen Koffer liegen {L("deutsche-bank-mastercard-travel")} und {L("commerzbank-premiumkreditkarte")} mit 4.000 € vorn (je 50 € Selbstbehalt), dahinter Amex Platinum, BMW Carbon mit 3.000 €, TF Bank, Advanzia und Klarna Max mit 2.500 €. Viele Gold-Karten der Filialbanken (Sparkasse, Postbank, Commerzbank Gold, easybank) haben gar keinen Gepäckschutz, Revolut Ultra und bunq nur 1.000 €. Wer mit Kamera oder Laptop reist, ist über die Karte selten ausreichend versichert.</p>
<p>So kommst du an das Geld: Fehlendes oder beschädigtes Gepäck sofort am Flughafen melden und den Property Irregularity Report (PIR) aufheben; bei Verspätung eine Bestätigung der Airline über Dauer und Grund verlangen; nur Belege einreichen; zuerst die Airline in Anspruch nehmen, dann die Kartenversicherung, die nach dem Ergebnis fragt. Reagiert die Airline nicht, hilft in Deutschland die Schlichtungsstelle Reise &amp; Verkehr (früher söp) für ihre Mitgliedsairlines, für alle anderen die Schlichtungsstelle Luftverkehr beim Bundesamt für Justiz.</p></div>'''),
       ('Selbstbehalt: von 0 € bis 20 % plus Mindestbetrag','''<div class="prose"><ul>
<li><b>Kein Selbstbehalt:</b> Deutsche Bank Travel, Miles &amp; More HON Circle.</li>
<li><b>Fixbetrag:</b> N26 20 € pro Person; TF Bank 100 € pro Person; Postbank Gold 100 €; bunq 50 €; 1822direkt 102 €, bei Krankheit 20 %; Eurowings 100 €, bei Krankheit 20 %.</li>
<li><b>10 % mit Mindestbetrag:</b> American Express, BMW, Miles &amp; More Gold, Frequent Traveller und Senator, Deutschland-Kreditkarte Gold, Openbank, Tomorrow (je mindestens 100 €).</li>
<li><b>20 % mit Mindestbetrag:</b> Advanzia und baugleiche Karten (mindestens 100 €), Consorsbank, Commerzbank und Targobank (mindestens 100 € beziehungsweise 200 €), easybank Gold (mindestens 200 €), Bank Norwegian (mindestens 185 €).</li>
<li><b>Nicht genannt:</b> Hanseatic, HypoVereinsbank, Sparkasse, Postbank Platinum, easybank Platinum, ADAC. Dort steht in den Dokumenten, die wir ausgewertet haben, kein Selbstbehalt; vor einer Buchung nachfragen.</li></ul>
<p>Bei einer 4.000-Euro-Reise sind 20 % immerhin 800 €. Karten mit Fixbetrag (N26, TF Bank, Postbank Gold) oder ohne Selbstbehalt sind bei teuren Reisen deshalb spürbar besser als ihre Stornosumme allein zeigt.</p></div>'''),
       ('Wer ist mitversichert?','''<div class="prose"><p>Die Regeln reichen von „nur der Karteninhaber“ bis „Familie, auch ohne Karteneinsatz“:</p><ul>
<li><b>Nur der Karteninhaber</b> bei der Krankenversicherung: Commerzbank Gold.</li>
<li><b>Familie auf gemeinsamen Reisen:</b> TF Bank (bis 4 Mitreisende), Advanzia und baugleiche Karten (Partner und Kinder), Deutschland-Kreditkarte Gold (Partner, Kinder unter 25), easybank Gold (Partner, Kinder bis 18), Deutsche Bank Travel und Miles &amp; More (Partner, Kinder bis 25), Eurowings (Partner, Kinder bis 25), Sparkasse Gold (bis 6 Personen), ADAC (bis 5 Mitreisende), Tomorrow (Kinder bis 18 bzw. 27), bunq (Partner, Kinder unter 19), Revolut Ultra (Kinder bis 17).</li>
<li><b>Familie auch ohne Karteneinsatz</b> bei der Krankenversicherung: Postbank, HypoVereinsbank (Family-Paket), Targobank Premium, ADAC, Miles &amp; More.</li>
<li><b>Family-Summen:</b> Postbank 10.400 € und easybank Platinum 10.300 € je Familie statt 5.200 € je Karteninhaber; HypoVereinsbank 7.500 € (Family) statt 5.000 €.</li></ul></div>'''),
       ('Reicht die Kreditkarte, oder brauchst du eine eigene Police?','''<div class="prose"><p>Die Kreditkarten-Versicherung reicht in der Regel, wenn alle fünf Punkte zutreffen: Die Reise kostet weniger als die Stornosumme deiner Karte, sie dauert kürzer als die erlaubte Höchstdauer, du bist unter der Altersgrenze, du hast die Reise im geforderten Umfang mit der Karte bezahlt, und es reisen nur Personen mit, die laut Bedingungen mitversichert sind.</p>
<p>Eine eigene Reiseversicherung brauchst du, wenn die Pauschalreise für die Familie 6.000 € kostet und deine Karte 5.000 € mit 20 % Selbstbehalt versichert; wenn jemand über 75 mitreist; wenn eine Vorerkrankung besteht, denn die ist bei fast allen Karten ausgeschlossen; wenn du länger als 60 bis 90 Tage unterwegs bist; oder wenn du einen Mietwagen nimmst und keine der Karten mit Vollkasko hast. Auch Kreuzfahrten, Sportreisen und Länder mit Reisewarnung sind häufig ausgeschlossen.</p>
<p>Ein Mittelweg, der in Deutschland besonders gut funktioniert: Die Krankenversicherung über eine Gold-Karte nutzen, die ohne Karteneinsatz und für die Familie gilt (Sparkasse, Postbank, Commerzbank, HypoVereinsbank, Miles &amp; More), und nur den Storno für die eine teure Reise separat versichern. Eine eigene Jahres-Auslandskrankenversicherung kostet oft weniger als eine Gold-Karte und hat keine Reisedauer-Grenze von 45 oder 62 Tagen.</p></div>'''),
       ('Was im Schadenfall zu tun ist','''<div class="prose"><p>Vor jeder Behandlung im Ausland die Notfallnummer der Versicherung anrufen, nicht die der Bank; bei den meisten Paketen ist das Allianz Partners (AWP), HanseMerkur, AmTrust oder Lloyd's. Belege aufheben: Buchungsbestätigung, Kartenabrechnung mit der Reisezahlung, ärztliches Attest beim Storno, Polizeiprotokoll bei Diebstahl, PIR beim Gepäck. Die Reise sofort absagen, sobald der Grund eintritt, sonst zahlt die Versicherung nur die Stornokosten, die zu diesem Zeitpunkt angefallen wären. Bei Krankenversicherungen mit Selbstbehalt bis 500 € (American Express, BMW) lohnt sich die Europäische Krankenversicherungskarte als erste Anlaufstelle im EU-Ausland.</p></div>'''),
       ('Quellen',f'''<div class="prose"><ul>
<li>Versicherungssummen und Bedingungen: Versicherungsbedingungen und Leistungsübersichten der Anbieter, verlinkt auf jeder Kartenseite; wo nur ein Vergleichsportal vorlag, steht das in der Tabelle.</li>
<li>EU-Fluggastrechte (Verordnung 261/2004): Beträge und Betreuung nach der Übersicht der {Q_EU}.</li>
<li>Montrealer Übereinkommen, Fristen und Property Irregularity Report: {Q_MC}.</li>
<li>Schlichtungsstellen für Flugbeschwerden in Deutschland: {Q_ADR}.</li></ul></div>'''),
      ],
      faq=[
       ('Welche kostenlose Kreditkarte hat in Deutschland eine Reiseversicherung mit Storno?','TF Bank Mastercard Gold und Advanzia Gebührenfrei Mastercard Gold (baugleich: GMX/WEB.DE WEB.Cent) versichern Reiserücktritt bis 3.000 € und Arztkosten bis 1.000.000 €. Die Bank Norwegian Visa nennt einen Reiserücktritt, die Summen kennen wir nur aus zweiter Hand. Advanzia versichert nur Reisen außerhalb Deutschlands.'),
       ('Gilt die Reiseversicherung der Kreditkarte auch ohne Karteneinsatz?','Die Auslandskrankenversicherung oft ja: Sparkasse Gold, Postbank, Commerzbank Gold und Premium, HypoVereinsbank Gold, Miles & More, ADAC und Targobank Premium versichern Arztkosten, sobald du die Karte besitzt. Der Reiserücktritt verlangt fast überall, dass die Reise zur Hälfte oder ganz mit der Karte bezahlt wurde; Ausnahmen sind HypoVereinsbank, Commerzbank und N26.'),
       ('Welche Kreditkarte hat die höchste Reiserücktrittsversicherung?','N26 Go und Metal, Consorsbank Visa Card Gold, Openbank Bestcard Premium, die ADAC-Pakete und die Miles & More HON Circle Card mit 10.000 €, dahinter Targobank Premium mit 7.500 € und American Express Platinum sowie BMW Carbon mit 6.000 € pro Person.'),
       ('Welche Kreditkarte hat eine Mietwagen-Vollkasko?','American Express Platinum (75.000 €), Miles & More Gold, Frequent Traveller und Senator (75.000 €), HON Circle (100.000 €), Eurowings Premium (75.000 €), Targobank Premium, easybank Platinum (100.000 €), Openbank Bestcard Premium und BMW Carbon. Consorsbank Gold, bunq Elite und ADAC decken nur den Selbstbehalt des Vermieters bis 1.500 bzw. 3.000 €.'),
       ('Wie lange gilt die Auslandskrankenversicherung der Kreditkarte pro Reise?','Meist 45 bis 90 Tage: ADAC und HypoVereinsbank 45, Sparkasse 56, Openbank 60, Postbank, Commerzbank, Tomorrow und Amex Gold 62, Advanzia, Deutsche Bank und Miles & More 90, Amex Platinum und BMW 120 Tage. Revolut Premium und Metal nur 30 Tage.'),
       ('Zahlt die Kreditkarte bei Flugverspätung zusätzlich zur Airline?','Ja, die Ansprüche sind getrennt. Die Airline schuldet die Ausgleichszahlung nach EU-Recht ab drei Stunden (250 bis 600 €), die Kartenversicherung ersetzt belegte Ausgaben ab ihrer eigenen Schwelle, bei Amex Gold ab vier Stunden 175 €, bei N26 bis 500 €, bei Advanzia 250 €. Was die Airline schon ersetzt hat, zahlt die Karte nicht noch einmal.'),
       ('Was ist mit Gepäck, das verloren geht?','Die Airline haftet nach dem Montrealer Übereinkommen bis rund 1.900 €, nach 21 Tagen gilt der Koffer als verloren. Darüber hinaus zahlt die Kartenversicherung bis zu ihrer Summe: Deutsche Bank Travel und Commerzbank Premium 4.000 €, Amex Platinum und BMW 3.000 €, TF Bank, Advanzia und Klarna Max 2.500 €. Viele Gold-Karten der Filialbanken haben keinen Gepäckschutz.'),
       ('Bis zu welchem Alter gilt die Reiseversicherung der Kreditkarte?','Bank Norwegian bis einschließlich 65, TF Bank und Advanzia bis 75 (Advanzia ab 70 nur 21 Tage pro Reise), Sparkasse Gold bei der Krankenversicherung bis 75. Die übrigen Anbieter nennen in den ausgewerteten Bedingungen keine Grenze; nachfragen lohnt sich.'),
      ],
      related=['bargeld-abheben','mietwagen-kaution','kostenlose-kreditkarte'])
